    assertTrue(text.contains(expected), () -> "generated source is missing:\n" + expected);
  }

  private static void assertDoesNotContain(String text, String unexpected) {
    assertFalse(text.contains(unexpected), () -> "generated source unexpectedly contains:\n" + unexpected);
  }

