/** Tests for {@link PropertiesDrivenCryptoFactory#getFileEncryptionProperties}. */
class PropertiesDrivenCryptoFactoryGetFileEncryptionPropertiesTests {

  private static final String FOOTER_KEY_ID = "footerMasterKey";
  private static final String COLUMN_KEY_ID_1 = "columnMasterKey1";
  private static final String COLUMN_KEY_ID_2 = "columnMasterKey2";
  private static final String UNIFORM_KEY_ID = "uniformMasterKey";

  private static final String FOOTER_KEY_PROPERTY = PropertiesDrivenCryptoFactory.FOOTER_KEY_PROPERTY_NAME;
  private static final String COLUMN_KEYS_PROPERTY = PropertiesDrivenCryptoFactory.COLUMN_KEYS_PROPERTY_NAME;
  private static final String UNIFORM_KEY_PROPERTY = PropertiesDrivenCryptoFactory.UNIFORM_KEY_PROPERTY_NAME;
  private static final String ALGORITHM_PROPERTY = PropertiesDrivenCryptoFactory.ENCRYPTION_ALGORITHM_PROPERTY_NAME;
  private static final String PLAINTEXT_FOOTER_PROPERTY = PropertiesDrivenCryptoFactory.PLAINTEXT_FOOTER_PROPERTY_NAME;
  private static final String COMPLETE_COLUMNS_PROPERTY =
      PropertiesDrivenCryptoFactory.COMPLETE_COLUMN_ENCRYPTION_PROPERTY_NAME;

  private final PropertiesDrivenCryptoFactory factory = new PropertiesDrivenCryptoFactory();

  // ---------------------------------------------------------------- helpers

  private static Configuration baseConfig() {
    Configuration configuration = new Configuration();
    configuration.set(KeyToolkit.KMS_CLIENT_CLASS_PROPERTY_NAME, InMemoryLocalWrapKmsClient.class.getName());
    return configuration;
  }

  private FileEncryptionProperties properties(Configuration configuration) {
    return factory.getFileEncryptionProperties(configuration, null, null);
  }

  private FileEncryptionProperties properties(Configuration configuration, Path tempFilePath) {
    return factory.getFileEncryptionProperties(configuration, tempFilePath, null);
  }

  private static String asString(byte[] bytes) {
    assertThat(bytes).isNotNull();
    return new String(bytes, StandardCharsets.UTF_8);
  }

  private static Path localPath(File dir, String name) {
    return new Path(new Path(dir.toURI()), name);
  }

  // ------------------------------------------------------- no configuration

  @Test
  void returnsNullWhenNoEncryptionPropertyIsSet() {
    assertThat(properties(baseConfig())).isNull();
  }

  @Test
  void returnsNullWhenOnlyEmptyValuesAreConfigured() {
    Configuration configuration = baseConfig();
    configuration.set(FOOTER_KEY_PROPERTY, "");
    configuration.set(COLUMN_KEYS_PROPERTY, "");
    configuration.set(UNIFORM_KEY_PROPERTY, "");

    assertThat(properties(configuration)).isNull();
  }

  @Test
  void returnsNullWhenValuesAreOnlyWhitespace() {
    Configuration configuration = baseConfig();
    configuration.set(FOOTER_KEY_PROPERTY, "   ");
    configuration.set(COLUMN_KEYS_PROPERTY, "  ");
    configuration.set(UNIFORM_KEY_PROPERTY, " ");

    assertThat(properties(configuration)).isNull();
  }

  // --------------------------------------------- non-uniform mode, footer key

  @Test
  void throwsWhenOnlyFooterKeyIsConfigured() {
    Configuration configuration = baseConfig();
    configuration.set(FOOTER_KEY_PROPERTY, FOOTER_KEY_ID);

    assertThatThrownBy(() -> properties(configuration))
        .isInstanceOf(ParquetCryptoRuntimeException.class)
        .hasMessage("No column keys configured in " + COLUMN_KEYS_PROPERTY);
  }

  @Test
  void throwsWhenOnlyColumnKeysAreConfigured() {
    Configuration configuration = baseConfig();
    configuration.set(COLUMN_KEYS_PROPERTY, COLUMN_KEY_ID_1 + ":a");

    assertThatThrownBy(() -> properties(configuration))
        .isInstanceOf(ParquetCryptoRuntimeException.class)
        .hasMessage("No footer key configured in " + FOOTER_KEY_PROPERTY);
  }

  @Test
  void createsColumnKeysForEachConfiguredColumn() {
    Configuration configuration = baseConfig();
    configuration.set(FOOTER_KEY_PROPERTY, FOOTER_KEY_ID);
    configuration.set(COLUMN_KEYS_PROPERTY, COLUMN_KEY_ID_1 + ":a,b;" + COLUMN_KEY_ID_2 + ":c.d");

    FileEncryptionProperties properties = properties(configuration);

    Map<org.apache.parquet.hadoop.metadata.ColumnPath, ColumnEncryptionProperties> columns =
        properties.getEncryptedColumns();
    assertThat(columns).hasSize(3).containsOnlyKeys(
        org.apache.parquet.hadoop.metadata.ColumnPath.fromDotString("a"),
        org.apache.parquet.hadoop.metadata.ColumnPath.fromDotString("b"),
        org.apache.parquet.hadoop.metadata.ColumnPath.fromDotString("c.d"));

    for (ColumnEncryptionProperties columnProperties : columns.values()) {
      assertThat(columnProperties.isEncrypted()).isTrue();
      assertThat(columnProperties.isEncryptedWithFooterKey()).isFalse();
      assertThat(columnProperties.getKeyBytes()).hasSize(16);
      assertThat(columnProperties.getKeyMetaData()).isNotNull().isNotEmpty();
    }

    byte[] footerKey = properties.getFooterKey();
    assertThat(footerKey).hasSize(16);
    for (ColumnEncryptionProperties columnProperties : columns.values()) {
      assertThat(columnProperties.getKeyBytes()).isNotEqualTo(footerKey);
    }
    // default data key length is 128 bits
    assertThat(properties.encryptedFooter()).isTrue();
    assertThat(properties.getAlgorithm().isSetAES_GCM_V1()).isTrue();
  }

  @Test
  void storesMasterKeyIdsAndKmsInstanceInFooterKeyMetadata() {
    Configuration configuration = baseConfig();
    configuration.set(KeyToolkit.KMS_INSTANCE_ID_PROPERTY_NAME, "kmsInstanceForTest");
    configuration.set(FOOTER_KEY_PROPERTY, FOOTER_KEY_ID);
    configuration.set(COLUMN_KEYS_PROPERTY, COLUMN_KEY_ID_1 + ":a");

    FileEncryptionProperties properties = properties(configuration);

    String footerKeyMetadata = asString(properties.getFooterKeyMetadata());
    assertThat(footerKeyMetadata)
        .contains("PKMT1")
        .contains("\"internalStorage\":true")
        .contains("\"isFooterKey\":true")
        .contains("\"masterKeyID\":\"" + FOOTER_KEY_ID + "\"")
        .contains("\"kmsInstanceID\":\"kmsInstanceForTest\"")
        .doesNotContain("keyReference");

    ColumnEncryptionProperties columnProperties = properties.getColumnProperties(
        org.apache.parquet.hadoop.metadata.ColumnPath.fromDotString("a"));
    assertThat(asString(columnProperties.getKeyMetaData()))
        .contains("\"isFooterKey\":false")
        .contains("\"masterKeyID\":\"" + COLUMN_KEY_ID_1 + "\"");
  }

