  @ParameterizedTest
  @ValueSource(ints = {128, 192, 256})
  void acceptsSupportedDataKeyLengths(int keyLengthBits) {
    Configuration configuration = baseConfig();
    configuration.set(FOOTER_KEY_PROPERTY, FOOTER_KEY_ID);
    configuration.set(COLUMN_KEYS_PROPERTY, COLUMN_KEY_ID_1 + ":a");
    configuration.setInt(KeyToolkit.DATA_KEY_LENGTH_PROPERTY_NAME, keyLengthBits);

    FileEncryptionProperties properties = properties(configuration);

    int expectedBytes = keyLengthBits / 8;
    assertThat(properties.getFooterKey()).hasSize(expectedBytes);
    assertThat(properties.getEncryptedColumns().values())
        .allSatisfy(columnProperties ->
            assertThat(columnProperties.getKeyBytes()).hasSize(expectedBytes));
  }

