  @Test
  void writesKeyMaterialFileWhenKeyMaterialIsStoredExternally(@TempDir File tempDir) throws IOException {
    Configuration configuration = baseConfig();
    configuration.set(FOOTER_KEY_PROPERTY, FOOTER_KEY_ID);
    configuration.set(COLUMN_KEYS_PROPERTY, COLUMN_KEY_ID_1 + ":a");
    configuration.setBoolean(KeyToolkit.KEY_MATERIAL_INTERNAL_PROPERTY_NAME, false);

    Path tempFilePath = localPath(tempDir, "data.parquet");
    FileEncryptionProperties properties = properties(configuration, tempFilePath);

    String footerKeyMetadata = asString(properties.getFooterKeyMetadata());
    assertThat(footerKeyMetadata)
        .contains("\"internalStorage\":false")
        .contains("\"keyReference\":\"footerKey\"")
        .doesNotContain("wrappedDEK");

    String columnKeyMetadata = asString(
        properties.getEncryptedColumns().values().iterator().next().getKeyMetaData());
    assertThat(columnKeyMetadata).contains("\"internalStorage\":false").contains("\"keyReference\":\"columnKey0\"");

    File keyMaterialFile = new File(
        tempDir,
        HadoopFSKeyMaterialStore.KEY_MATERIAL_FILE_PREFIX + "data.parquet"
            + HadoopFSKeyMaterialStore.KEY_MATERIAL_FILE_SUFFFIX);
    assertThat(keyMaterialFile).exists();
    String keyMaterial = new String(Files.readAllBytes(keyMaterialFile.toPath()), StandardCharsets.UTF_8);
    assertThat(keyMaterial)
        .contains("PKMT1")
        .contains("footerKey")
        .contains("columnKey0")
        .contains(FOOTER_KEY_ID)
        .contains(COLUMN_KEY_ID_1);
  }

