  void failsWhenKeyMaterialCannotBeSaved(@TempDir File tempDir) throws IOException {
    File notADirectory = new File(tempDir, "not-a-directory");
    assertThat(notADirectory.createNewFile()).isTrue();
    Configuration configuration = baseConfig();
    configuration.set(UNIFORM_KEY_PROPERTY, UNIFORM_KEY_ID);
    configuration.setBoolean(KeyToolkit.KEY_MATERIAL_INTERNAL_PROPERTY_NAME, false);

    Path tempFilePath = new Path(new Path(notADirectory.toURI()), "data.parquet");

    assertThatThrownBy(() -> properties(configuration, tempFilePath))
        .isInstanceOf(ParquetCryptoRuntimeException.class)
        .hasMessageContaining("Failed to save key material");
  }

