import org.apache.parquet.io.SeekableInputStream;
import org.apache.parquet.schema.MessageType;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import org.mockito.ArgumentCaptor;

class ParquetFileReaderReadBloomFilterTests {

  private static final int BLOOM_FILTER_BYTES = BlockSplitBloomFilter.LOWER_BOUND_BYTES;
  private static final long KNOWN_HASH = 0x123456789ABCDEFL;

  @Test
  void returnsNullWhenColumnHasNoBloomFilter() throws Exception {
    InMemorySeekableInputStream stream = new InMemorySeekableInputStream(new byte[] {1, 2, 3});
    ParquetFileReader reader = newReader(stream, null);
    ColumnChunkMetaData meta = columnMetadata(-1, 3);

    assertThat(reader.readBloomFilter(meta)).isNull();
    assertThat(stream.getPos()).isZero();
  }

  @Test
  void readsBloomFilterWhenLengthIsPresent() throws Exception {
    BloomFilter expected = bloomFilterWithKnownHash();
    byte[] serialized = serializeBloomFilter(expected);
    int offset = 19;
    InMemorySeekableInputStream stream = streamWithDataAt(offset, serialized);
    ParquetFileReader reader = newReader(stream, null);
    ColumnChunkMetaData meta = columnMetadata(offset, serialized.length);

    BloomFilter actual = reader.readBloomFilter(meta);

    assertThat(actual).isNotNull();
    assertThat(actual).isEqualTo(expected);
    assertThat(actual.getBitsetSize()).isEqualTo(BLOOM_FILTER_BYTES);
    assertThat(actual.findHash(KNOWN_HASH)).isTrue();
    assertThat(actual.findHash(0x0FEDCBA987654321L)).isFalse();
    assertThat(stream.getPos()).isEqualTo(offset + serialized.length);
  }

  @Test
  void readsBloomFilterWhenLengthIsNegative() throws Exception {
    BloomFilter expected = bloomFilterWithKnownHash();
    byte[] serialized = serializeBloomFilter(expected);
    int offset = 11;
    InMemorySeekableInputStream stream = streamWithDataAt(offset, serialized);
    ParquetFileReader reader = newReader(stream, null);
    ColumnChunkMetaData meta = columnMetadata(offset, -1);

    BloomFilter actual = reader.readBloomFilter(meta);

    assertThat(actual).isNotNull();
    assertThat(actual).isEqualTo(expected);
    assertThat(actual.findHash(KNOWN_HASH)).isTrue();
    assertThat(stream.getPos()).isEqualTo(offset + serialized.length);
  }

  @Test
  void returnsNullWhenBloomFilterHeaderCannotBeRead() throws Exception {
    byte[] header = serializeHeader(validHeader(BLOOM_FILTER_BYTES));
    byte[] truncatedHeader = Arrays.copyOf(header, header.length - 1);
    int offset = 7;
    InMemorySeekableInputStream stream = streamWithDataAt(offset, truncatedHeader);
    ParquetFileReader reader = newReader(stream, null);
    ColumnChunkMetaData meta = columnMetadata(offset, truncatedHeader.length);

    assertThat(reader.readBloomFilter(meta)).isNull();
  }

  @ParameterizedTest
  @ValueSource(ints = {0, -1, BlockSplitBloomFilter.UPPER_BOUND_BYTES + 1})
  void returnsNullForInvalidBloomFilterSize(int numBytes) throws Exception {
    byte[] header = serializeHeader(validHeader(numBytes));
    int offset = 3;
    InMemorySeekableInputStream stream = streamWithDataAt(offset, header);
    ParquetFileReader reader = newReader(stream, null);
    ColumnChunkMetaData meta = columnMetadata(offset, header.length);

    assertThat(reader.readBloomFilter(meta)).isNull();
  }

  @Test
  void returnsNullForUnsupportedBloomFilterAlgorithm() throws Exception {
    assertUnsupportedHeader(validHeader(BLOOM_FILTER_BYTES).setAlgorithm(new BloomFilterAlgorithm()));
  }

  @Test
  void returnsNullForUnsupportedBloomFilterHash() throws Exception {
    assertUnsupportedHeader(validHeader(BLOOM_FILTER_BYTES).setHash(new BloomFilterHash()));
  }

  @Test
  void returnsNullForUnsupportedBloomFilterCompression() throws Exception {
    assertUnsupportedHeader(validHeader(BLOOM_FILTER_BYTES).setCompression(new BloomFilterCompression()));
  }

  @Test
  void decryptsEncryptedBloomFilterAndUsesModuleSpecificAad() throws Exception {
    BloomFilter expected = bloomFilterWithKnownHash();
    byte[] serialized = serializeBloomFilter(expected);
    byte[] header = Arrays.copyOfRange(serialized, 0, serialized.length - BLOOM_FILTER_BYTES);
    byte[] bitset = Arrays.copyOfRange(serialized, serialized.length - BLOOM_FILTER_BYTES, serialized.length);

    BlockCipher.Decryptor decryptor = mock(BlockCipher.Decryptor.class);
    when(decryptor.decrypt(any(InputStream.class), any(byte[].class))).thenReturn(header, bitset);
    InternalFileDecryptor fileDecryptor = encryptedFileDecryptor(decryptor);

    int offset = 5;
    InMemorySeekableInputStream stream = streamWithDataAt(offset, serialized);
    ParquetFileReader reader = newReader(stream, fileDecryptor);
    ColumnChunkMetaData meta = columnMetadata(offset, serialized.length);

    BloomFilter actual = reader.readBloomFilter(meta);

    assertThat(actual).isEqualTo(expected);
    assertThat(actual.findHash(KNOWN_HASH)).isTrue();

    ArgumentCaptor<byte[]> aadCaptor = ArgumentCaptor.forClass(byte[].class);
    verify(decryptor, times(2)).decrypt(any(InputStream.class), aadCaptor.capture());
    byte[] fileAad = fileDecryptor.getFileAAD();
    assertThat(aadCaptor.getAllValues().get(0)).startsWith(fileAad);
    assertThat(aadCaptor.getAllValues().get(1)).startsWith(fileAad);
    assertThat(aadCaptor.getAllValues().get(0)[fileAad.length])
        .isEqualTo(ModuleType.BloomFilterHeader.getValue());
    assertThat(aadCaptor.getAllValues().get(1)[fileAad.length])
        .isEqualTo(ModuleType.BloomFilterBitset.getValue());
    assertThat(aadCaptor.getAllValues().get(0)).isEqualTo(AesCipher.createModuleAAD(
        fileAad, ModuleType.BloomFilterHeader, 7, 4, -1));
    assertThat(aadCaptor.getAllValues().get(1)).isEqualTo(AesCipher.createModuleAAD(
        fileAad, ModuleType.BloomFilterBitset, 7, 4, -1));
  }

  @Test
  void rejectsDecryptedBloomFilterBitsetWithWrongLength() throws Exception {
    byte[] serialized = serializeBloomFilter(bloomFilterWithKnownHash());
    byte[] header = Arrays.copyOfRange(serialized, 0, serialized.length - BLOOM_FILTER_BYTES);
    byte[] wrongLengthBitset = new byte[BLOOM_FILTER_BYTES - 1];

    BlockCipher.Decryptor decryptor = mock(BlockCipher.Decryptor.class);
    when(decryptor.decrypt(any(InputStream.class), any(byte[].class))).thenReturn(header, wrongLengthBitset);
    InternalFileDecryptor fileDecryptor = encryptedFileDecryptor(decryptor);

    int offset = 2;
    InMemorySeekableInputStream stream = streamWithDataAt(offset, serialized);
    ParquetFileReader reader = newReader(stream, fileDecryptor);
    ColumnChunkMetaData meta = columnMetadata(offset, serialized.length);

    assertThatThrownBy(() -> reader.readBloomFilter(meta))
        .isInstanceOf(ParquetCryptoRuntimeException.class)
        .hasMessageContaining("Wrong length of decrypted bloom filter bitset");
  }

  private static void assertUnsupportedHeader(BloomFilterHeader header) throws Exception {
    byte[] serializedHeader = serializeHeader(header);
    int offset = 4;
    InMemorySeekableInputStream stream = streamWithDataAt(offset, serializedHeader);
    ParquetFileReader reader = newReader(stream, null);
    ColumnChunkMetaData meta = columnMetadata(offset, serializedHeader.length);

    assertThat(reader.readBloomFilter(meta)).isNull();
  }

  private static InternalFileDecryptor encryptedFileDecryptor(BlockCipher.Decryptor decryptor) {
    InternalColumnDecryptionSetup columnSetup = mock(InternalColumnDecryptionSetup.class);
    when(columnSetup.isEncrypted()).thenReturn(true);
    when(columnSetup.getMetaDataDecryptor()).thenReturn(decryptor);
    when(columnSetup.getOrdinal()).thenReturn(4);

    InternalFileDecryptor fileDecryptor = mock(InternalFileDecryptor.class);
    when(fileDecryptor.plaintextFile()).thenReturn(false);
    when(fileDecryptor.getFileAAD()).thenReturn(new byte[] {10, 20, 30, 40});
    when(fileDecryptor.getColumnSetup(any(ColumnPath.class))).thenReturn(columnSetup);
    return fileDecryptor;
  }

  private static ColumnChunkMetaData columnMetadata(long offset, int length) {
    ColumnChunkMetaData metadata = mock(ColumnChunkMetaData.class);
    when(metadata.getBloomFilterOffset()).thenReturn(offset);
    when(metadata.getBloomFilterLength()).thenReturn(length);
    when(metadata.getPath()).thenReturn(ColumnPath.get("column"));
    when(metadata.getRowGroupOrdinal()).thenReturn(7);
    return metadata;
  }

  private static ParquetFileReader newReader(SeekableInputStream stream, InternalFileDecryptor fileDecryptor)
      throws IOException {
    MessageType schema = new MessageType("schema");
    FileMetaData fileMetadata = new FileMetaData(
        schema,
        Collections.emptyMap(),
        "test-version",
        fileDecryptor == null ? null : FileMetaData.EncryptionType.PLAINTEXT_FOOTER,
        fileDecryptor);
    ParquetMetadata footer = new ParquetMetadata(fileMetadata, Collections.emptyList());
    return new ParquetFileReader(
        mock(InputFile.class), footer, ParquetReadOptions.builder().build(), stream);
  }

  private static BloomFilter bloomFilterWithKnownHash() {
    BlockSplitBloomFilter filter = new BlockSplitBloomFilter(BLOOM_FILTER_BYTES);
    filter.insertHash(KNOWN_HASH);
    return filter;
  }

  private static BloomFilterHeader validHeader(int numBytes) {
    return new BloomFilterHeader()
        .setNumBytes(numBytes)
        .setAlgorithm(new BloomFilterAlgorithm().setBLOCK(new SplitBlockAlgorithm()))
        .setHash(new BloomFilterHash().setXXHASH(new XxHash()))
        .setCompression(new BloomFilterCompression().setUNCOMPRESSED(new Uncompressed()));
  }

  private static byte[] serializeHeader(BloomFilterHeader header) throws IOException {
    ByteArrayOutputStream out = new ByteArrayOutputStream();
    Util.writeBloomFilterHeader(header, out);
    return out.toByteArray();
  }

  private static byte[] serializeBloomFilter(BloomFilter filter) throws IOException {
    ByteArrayOutputStream out = new ByteArrayOutputStream();
    filter.writeTo(out);
    return out.toByteArray();
  }

  private static InMemorySeekableInputStream streamWithDataAt(int offset, byte[] data) {
    byte[] fileBytes = new byte[offset + data.length];
    System.arraycopy(data, 0, fileBytes, offset, data.length);
    return new InMemorySeekableInputStream(fileBytes);
  }

  private static final class InMemorySeekableInputStream extends SeekableInputStream {
    private final byte[] data;
    private int position;

    private InMemorySeekableInputStream(byte[] data) {
      this.data = data;
    }

    @Override
    public long getPos() {
      return position;
    }

    @Override
    public void seek(long newPos) throws IOException {
      if (newPos < 0 || newPos > data.length) {
        throw new IOException("Invalid seek position: " + newPos);
      }
      position = (int) newPos;
    }

    @Override
    public int read() {
      if (position >= data.length) {
        return -1;
      }
      return data[position++] & 0xFF;
    }

    @Override
    public int read(byte[] bytes, int start, int length) {
      if (position >= data.length) {
        return -1;
      }
      int bytesToRead = Math.min(length, data.length - position);
      System.arraycopy(data, position, bytes, start, bytesToRead);
      position += bytesToRead;
      return bytesToRead;
    }

    @Override
    public void readFully(byte[] bytes) throws IOException {
      readFully(bytes, 0, bytes.length);
    }

    @Override
    public void readFully(byte[] bytes, int start, int length) throws IOException {
      if (data.length - position < length) {
        throw new EOFException("Not enough bytes in test stream");
      }
      System.arraycopy(data, position, bytes, start, length);
      position += length;
    }

    @Override
    public int read(ByteBuffer buffer) {
      if (!buffer.hasRemaining()) {
        return 0;
      }
      if (position >= data.length) {
        return -1;
      }
      int bytesToRead = Math.min(buffer.remaining(), data.length - position);
      buffer.put(data, position, bytesToRead);
      position += bytesToRead;
      return bytesToRead;
    }

    @Override
    public void readFully(ByteBuffer buffer) throws IOException {
      int length = buffer.remaining();
      if (data.length - position < length) {
        throw new EOFException("Not enough bytes in test stream");
      }
      buffer.put(data, position, length);
      position += length;
    }
  }
