class ParquetFileReaderReadBloomFilterTests {

  private static final int BLOOM_FILTER_BYTES = BlockSplitBloomFilter.LOWER_BOUND_BYTES;
  private static final long KNOWN_HASH = 0x123456789ABCDEFL;

  @Test
  void returnsNullWhenColumnHasNoBloomFilter() throws Exception {
    InMemorySeekableInputStream stream = new InMemorySeekableInputStream(new byte[] {1, 2, 3});
    ParquetFileReader reader = newReader(stream, null);
    ColumnChunkMetaData meta = columnMetadata(-1, 3);

    assertThat(reader.readBloomFilter(meta)).isNull();
    assertThat(stream.getPos()).isZero();
  }

  @Test
  void readsBloomFilterWhenLengthIsPresent() throws Exception {
    BloomFilter expected = bloomFilterWithKnownHash();
    byte[] serialized = serializeBloomFilter(expected);
    int offset = 19;
    InMemorySeekableInputStream stream = streamWithDataAt(offset, serialized);
    ParquetFileReader reader = newReader(stream, null);
    ColumnChunkMetaData meta = columnMetadata(offset, serialized.length);

    BloomFilter actual = reader.readBloomFilter(meta);

    assertThat(actual).isNotNull();
    assertThat(actual).isEqualTo(expected);
    assertThat(actual.getBitsetSize()).isEqualTo(BLOOM_FILTER_BYTES);
    assertThat(actual.findHash(KNOWN_HASH)).isTrue();
    assertThat(actual.findHash(0x0FEDCBA987654321L)).isFalse();
    assertThat(stream.getPos()).isEqualTo(offset + serialized.length);
  }

  @Test
  void readsBloomFilterWhenLengthIsNegative() throws Exception {
    BloomFilter expected = bloomFilterWithKnownHash();
    byte[] serialized = serializeBloomFilter(expected);
    int offset = 11;
    InMemorySeekableInputStream stream = streamWithDataAt(offset, serialized);
    ParquetFileReader reader = newReader(stream, null);
    ColumnChunkMetaData meta = columnMetadata(offset, -1);

    BloomFilter actual = reader.readBloomFilter(meta);

    assertThat(actual).isNotNull();
    assertThat(actual).isEqualTo(expected);
    assertThat(actual.findHash(KNOWN_HASH)).isTrue();
    assertThat(stream.getPos()).isEqualTo(offset + serialized.length);
  }

  @Test
  void returnsNullWhenBloomFilterHeaderCannotBeRead() throws Exception {
    byte[] header = serializeHeader(validHeader(BLOOM_FILTER_BYTES));
    byte[] truncatedHeader = Arrays.copyOf(header, header.length - 1);
    int offset = 7;
    InMemorySeekableInputStream stream = streamWithDataAt(offset, truncatedHeader);
    ParquetFileReader reader = newReader(stream, null);
    ColumnChunkMetaData meta = columnMetadata(offset, truncatedHeader.length);

    assertThat(reader.readBloomFilter(meta)).isNull();
  }

  @ParameterizedTest
  @ValueSource(ints = {0, -1, BlockSplitBloomFilter.UPPER_BOUND_BYTES + 1})
  void returnsNullForInvalidBloomFilterSize(int numBytes) throws Exception {
    byte[] header = serializeHeader(validHeader(numBytes));
    int offset = 3;
    InMemorySeekableInputStream stream = streamWithDataAt(offset, header);
    ParquetFileReader reader = newReader(stream, null);
    ColumnChunkMetaData meta = columnMetadata(offset, header.length);

    assertThat(reader.readBloomFilter(meta)).isNull();
  }

  @Test
