    ParquetFileReader reader = newReader(stream, null);
    ColumnChunkMetaData meta = columnMetadata(offset, serializedHeader.length);

    assertThat(reader.readBloomFilter(meta)).isNull();
  }

  private static InternalFileDecryptor encryptedFileDecryptor(BlockCipher.Decryptor decryptor) {
    InternalColumnDecryptionSetup columnSetup = mock(InternalColumnDecryptionSetup.class);
    when(columnSetup.isEncrypted()).thenReturn(true);
    when(columnSetup.getMetaDataDecryptor()).thenReturn(decryptor);
    when(columnSetup.getOrdinal()).thenReturn(4);

    InternalFileDecryptor fileDecryptor = mock(InternalFileDecryptor.class);
    when(fileDecryptor.plaintextFile()).thenReturn(false);
    when(fileDecryptor.getFileAAD()).thenReturn(new byte[] {10, 20, 30, 40});
    when(fileDecryptor.getColumnSetup(any(ColumnPath.class))).thenReturn(columnSetup);
    return fileDecryptor;
