  private static ColumnChunkMetaData columnMetadata(long offset, int length) {
    ColumnChunkMetaData metadata = mock(ColumnChunkMetaData.class);
    when(metadata.getBloomFilterOffset()).thenReturn(offset);
    when(metadata.getBloomFilterLength()).thenReturn(length);
    when(metadata.getPath()).thenReturn(ColumnPath.get("column"));
    when(metadata.getRowGroupOrdinal()).thenReturn(7);
    return metadata;
