```java
private static final class QueuedHeaderDecryptor implements BlockCipher.Decryptor {
  private final Iterator<byte[]> headers;
  private final List<byte[]> aads = new ArrayList<>();
  QueuedHeaderDecryptor(List<byte[]> headers) { this.headers = headers.iterator(); }
  @Override public byte[] decrypt(byte[] lengthAndCiphertext, byte[] aad) { throw new UnsupportedOperationException("unexpected"); }
  @Override public ByteBuffer decrypt(ByteBuffer from, byte[] aad) { throw new UnsupportedOperationException("unexpected"); }
  @Override public byte[] decrypt(InputStream from, byte[] aad) throws IOException {
    aads.add(aad == null ? null : aad.clone());
    if (!headers.hasNext()) throw new IOException("unexpected page header decryption call");
    byte[] header = headers.next();
    byte[] read = new byte[header.length];
    int off = 0;
    while (off < read.length) {
      int n = from.read(read, off, read.length - off);
      if (n < 0) throw new IOException("unexpected end of stream");
      off += n;
    }
    return header;
  }
}
```
