    assertThat(e.getMessage()).startsWith("more than one dictionary page in column");
    assertThat(e.getMessage()).contains(COLUMN);
  }

  @Test
  void tooFewValuesReadFailsWithIOException() throws Exception {
    ParquetFileReader reader = newReader(defaultOptions());
    ColumnChunkMetaData meta = metadata(false, 5L);
    byte[] values = payload(4, 1);
    Object chunk =
        newChunk(reader, meta, buffers(page(dataPageV1Header(2, 8, values.length, null), values)), null, 5L);

    IOException e = assertThrows(IOException.class, () -> readAllPages(chunk, null, null, null, -1, -1));
    assertThat(e.getMessage()).contains("Expected 5 values in column chunk at");
    assertThat(e.getMessage()).contains("but got 2 values instead over 1 pages");
  }

  @Test
  void tooManyValuesReadFailsWithIOException() throws Exception {
    ParquetFileReader reader = newReader(defaultOptions());
    ColumnChunkMetaData meta = metadata(false, 2L);
    byte[] firstValues = payload(4, 1);
    byte[] secondValues = payload(4, 2);
    Object chunk = newChunk(
        reader,
