class ParquetOutputCommitterWriteMetaDataFileTests {

  private static final MessageType SCHEMA = parseMessageType("message test_record {"
      + " required int32 id;"
      + " optional binary name (UTF8);"
      + "}");

  @TempDir
  private java.nio.file.Path tempDir;

  private Configuration configuration;
  private Path outputPath;

  @BeforeEach
  void setUp() {
    configuration = new Configuration();
    configuration.set("fs.defaultFS", "file:///");
    outputPath = new Path(tempDir.toUri());
  }

  @Test
  void writesMetadataAndCommonMetadataForAllLevel() throws Exception {
    configuration.set(ParquetOutputFormat.JOB_SUMMARY_LEVEL, JobSummaryLevel.ALL.name());
    Path dataFile = writeParquetFile("part-00000.parquet");
    ParquetMetadata dataMetadata = readMetadata(dataFile);

    ParquetOutputCommitter.writeMetaDataFile(configuration, outputPath);

    Path metadataFile = new Path(outputPath, ParquetFileWriter.PARQUET_METADATA_FILE);
    Path commonMetadataFile = new Path(outputPath, ParquetFileWriter.PARQUET_COMMON_METADATA_FILE);
    FileSystem fileSystem = outputPath.getFileSystem(configuration);

    assertThat(fileSystem.exists(metadataFile)).isTrue();
    assertThat(fileSystem.exists(commonMetadataFile)).isTrue();

    ParquetMetadata metadata = readMetadata(metadataFile);
    ParquetMetadata commonMetadata = readMetadata(commonMetadataFile);
    assertThat(dataMetadata.getBlocks()).isNotEmpty();
    assertThat(metadata.getBlocks()).hasSameSizeAs(dataMetadata.getBlocks());
    assertThat(commonMetadata.getBlocks()).isEmpty();
    assertThat(metadata.getFileMetaData().getSchema()).isEqualTo(SCHEMA);
    assertThat(commonMetadata.getFileMetaData().getSchema()).isEqualTo(SCHEMA);
  }

  @Test
  void writesOnlyCommonMetadataForCommonOnlyLevel() throws Exception {
    configuration.set(ParquetOutputFormat.JOB_SUMMARY_LEVEL, JobSummaryLevel.COMMON_ONLY.name());
    writeParquetFile("part-00000.parquet");

    ParquetOutputCommitter.writeMetaDataFile(configuration, outputPath);

    Path metadataFile = new Path(outputPath, ParquetFileWriter.PARQUET_METADATA_FILE);
    Path commonMetadataFile = new Path(outputPath, ParquetFileWriter.PARQUET_COMMON_METADATA_FILE);
    FileSystem fileSystem = outputPath.getFileSystem(configuration);

    assertThat(fileSystem.exists(metadataFile)).isFalse();
    assertThat(fileSystem.exists(commonMetadataFile)).isTrue();

    ParquetMetadata commonMetadata = readMetadata(commonMetadataFile);
    assertThat(commonMetadata.getBlocks()).isEmpty();
    assertThat(commonMetadata.getFileMetaData().getSchema()).isEqualTo(SCHEMA);
  }

  @Test
  void usesAllSummaryLevelWhenConfigurationDoesNotSpecifyOne() throws Exception {
    assertThat(ParquetOutputFormat.getJobSummaryLevel(configuration)).isEqualTo(JobSummaryLevel.ALL);
    writeParquetFile("part-00000.parquet");

    ParquetOutputCommitter.writeMetaDataFile(configuration, outputPath);

    FileSystem fileSystem = outputPath.getFileSystem(configuration);
    assertThat(fileSystem.exists(new Path(outputPath, ParquetFileWriter.PARQUET_METADATA_FILE)))
        .isTrue();
    assertThat(fileSystem.exists(new Path(outputPath, ParquetFileWriter.PARQUET_COMMON_METADATA_FILE)))
        .isTrue();
  }

  @Test
  void writesNoSummaryFilesForAnEmptyOutputDirectory() throws Exception {
    configuration.set(ParquetOutputFormat.JOB_SUMMARY_LEVEL, JobSummaryLevel.ALL.name());

    ParquetOutputCommitter.writeMetaDataFile(configuration, outputPath);

