    assertThat(fileSystem.exists(new Path(outputPath, ParquetFileWriter.PARQUET_METADATA_FILE)))
        .isFalse();
    assertThat(fileSystem.exists(new Path(outputPath, ParquetFileWriter.PARQUET_COMMON_METADATA_FILE)))
        .isFalse();
  }

  @Test
  void leavesExistingSummaryFilesUntouchedForNoneLevel() throws Exception {
    configuration.set(ParquetOutputFormat.JOB_SUMMARY_LEVEL, JobSummaryLevel.NONE.name());
    Files.writeString(tempDir.resolve(ParquetFileWriter.PARQUET_METADATA_FILE), "metadata-sentinel");
    Files.writeString(tempDir.resolve(ParquetFileWriter.PARQUET_COMMON_METADATA_FILE), "common-sentinel");

    ParquetOutputCommitter.writeMetaDataFile(configuration, outputPath);

    assertThat(Files.readString(tempDir.resolve(ParquetFileWriter.PARQUET_METADATA_FILE)))
        .isEqualTo("metadata-sentinel");
    assertThat(Files.readString(tempDir.resolve(ParquetFileWriter.PARQUET_COMMON_METADATA_FILE)))
        .isEqualTo("common-sentinel");
  }

  @Test
  void ignoresMissingOutputPath() throws Exception {
    configuration.set(ParquetOutputFormat.JOB_SUMMARY_LEVEL, JobSummaryLevel.ALL.name());
    java.nio.file.Path missing = tempDir.resolve("missing-directory");
    Path missingOutputPath = new Path(missing.toUri());

    assertThatCode(() -> ParquetOutputCommitter.writeMetaDataFile(configuration, missingOutputPath))
        .doesNotThrowAnyException();

    assertThat(Files.exists(missing)).isFalse();
  }

  @Test
  void propagatesInvalidSummaryLevelBeforeAccessingTheOutputPath() {
    configuration.set(ParquetOutputFormat.JOB_SUMMARY_LEVEL, "not-a-summary-level");

    assertThatThrownBy(() -> ParquetOutputCommitter.writeMetaDataFile(configuration, outputPath))
        .isInstanceOf(IllegalArgumentException.class)
        .hasMessageContaining("NOT-A-SUMMARY-LEVEL");
  }

  @Test
  void removesSummaryPathsWhenWritingMetadataFails() throws Exception {
    configuration.set(ParquetOutputFormat.JOB_SUMMARY_LEVEL, JobSummaryLevel.ALL.name());
    writeParquetFile("part-00000.parquet");
    Files.createDirectory(tempDir.resolve(ParquetFileWriter.PARQUET_METADATA_FILE));
    Files.createDirectory(tempDir.resolve(ParquetFileWriter.PARQUET_COMMON_METADATA_FILE));

    ParquetOutputCommitter.writeMetaDataFile(configuration, outputPath);

    FileSystem fileSystem = outputPath.getFileSystem(configuration);
    assertThat(fileSystem.exists(new Path(outputPath, ParquetFileWriter.PARQUET_METADATA_FILE)))
        .isFalse();
    assertThat(fileSystem.exists(new Path(outputPath, ParquetFileWriter.PARQUET_COMMON_METADATA_FILE)))
        .isFalse();
  }

  private Path writeParquetFile(String fileName) throws IOException {
    Path file = new Path(outputPath, fileName);
    SimpleGroupFactory groupFactory = new SimpleGroupFactory(SCHEMA);
    try (ExampleParquetWriter writer = (ExampleParquetWriter) ExampleParquetWriter.builder(file)
        .withConf(configuration)
        .withType(SCHEMA)
        .build()) {
      Group first = groupFactory.newGroup().append("id", 1).append("name", "alice");
      Group second = groupFactory.newGroup().append("id", 2).append("name", "bob");
      writer.write(first);
      writer.write(second);
    }
    return file;
  }

  private ParquetMetadata readMetadata(Path file) throws IOException {
    try (ParquetFileReader reader = ParquetFileReader.open(HadoopInputFile.fromPath(file, configuration))) {
      return reader.getFooter();
    }
  }
}
